+    let m = cube(Point3::new(0.0, 0.0, 0.0), Point3::new(4.0, 4.0, 4.0));
+    let mut f = SdfField::from_mesh(&m.facets, CELL, FIELD_BAND).expect("box field");
+    let tool = SdfTool::Flat { r: 10.0, flank: 30.0 };
